"""Воспроизводимое оформление Markdown и PDF по фактическим результатам запуска."""
from pathlib import Path
import json, csv, html
import numpy as np
import matplotlib
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak, KeepTogether
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.enums import TA_CENTER, TA_JUSTIFY, TA_LEFT
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.utils import ImageReader

ROOT=Path(__file__).resolve().parent

def num(x,d=4):
    if isinstance(x,str): return x
    if x is None: return '—'
    if abs(x-round(x))<1e-9: return str(int(round(x)))
    return f'{x:.{d}f}'.rstrip('0').rstrip('.')

class Report:
    def __init__(self,lab,title):
        self.lab=lab; self.title=title; self.md=[]; self.story=[]
        fonts=Path(matplotlib.get_data_path())/'fonts/ttf'
        for name,file in [('Serif','DejaVuSerif.ttf'),('SerifB','DejaVuSerif-Bold.ttf'),('Sans','DejaVuSans.ttf')]:
            pdfmetrics.registerFont(TTFont(name,str(fonts/file)))
        self.body=ParagraphStyle('body',fontName='Serif',fontSize=10.5,leading=14.5,spaceAfter=6,alignment=TA_JUSTIFY,allowWidows=0,allowOrphans=0)
        self.head=ParagraphStyle('head',fontName='SerifB',fontSize=13,leading=17,spaceBefore=12,spaceAfter=7,keepWithNext=True)
        self.small=ParagraphStyle('small',fontName='Sans',fontSize=8,leading=11,spaceAfter=2)
        self.form=ParagraphStyle('formula',fontName='Sans',fontSize=10,leading=15,spaceBefore=3,spaceAfter=9)
        title_style=ParagraphStyle('title',fontName='SerifB',fontSize=17,leading=24,alignment=TA_CENTER,spaceAfter=15)
        center=ParagraphStyle('center',parent=self.body,alignment=TA_CENTER)
        self.story += [Spacer(1,30),Paragraph('Национальный исследовательский ядерный университет<br/>«МИФИ»',center),Spacer(1,45),
            Paragraph('МЕТОДЫ ОПТИМИЗАЦИИ<br/>ЛИНЕЙНОЕ ПРОГРАММИРОВАНИЕ',center),Spacer(1,35),
            Paragraph(f'Лабораторная работа № {lab}',title_style),Paragraph(title,title_style),Paragraph('Вариант 10',center),Spacer(1,60),
            Paragraph('Выполнил: Яковлев Иван<br/>Группа: Б24-517<br/>Номер в группе: 28',self.body),Spacer(1,65),
            Paragraph('Москва 2026<br/>Осенний семестр',center),PageBreak()]
        self.md += [f'# Лабораторная работа № {lab}\n\n{title}\n',
            '**Яковлев Иван · Б24-517 · № 28 · осенний семестр 2026 года**\n\nВариант 10; seed 10128.\n']
    def h(self,text):
        self.md.append('## '+text+'\n'); self.story.append(Paragraph(html.escape(text),self.head))
    def p(self,text):
        self.md.append(text+'\n'); self.story.append(Paragraph(html.escape(text).replace('\n','<br/>'),self.body))
    def formula(self,text):
        self.md.append('```text\n'+text+'\n```\n'); self.story.append(Paragraph(html.escape(text).replace('\n','<br/>'),self.form))
    def table(self,headers,rows,widths=None):
        self.md.append('| '+' | '.join(map(str,headers))+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(str(v) for v in r)+' |' for r in rows)+'\n')
        data=[[Paragraph(html.escape(str(v)),self.small) for v in row] for row in [headers]+rows]
        t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
        t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e9edf1')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#c5c5c5')),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
        if len(rows)>12 and isinstance(self.story[-1],Paragraph): self.story[-1].keepWithNext=False
        if len(rows)<=8:
            group=[t]
            if isinstance(self.story[-1],Paragraph) and self.story[-1].style==self.head: group.insert(0,self.story.pop())
            self.story.append(KeepTogether(group))
        else: self.story.append(t)
        self.story.append(Spacer(1,8))
    def image(self,file,caption,maxheight=300):
        path=ROOT/'results'/file
        w,h=ImageReader(str(path)).getSize(); scale=min(480/w,maxheight/h)
        self.md.append(f'![{caption}](results/{file})\n')
        self.story.append(KeepTogether([Image(str(path),width=w*scale,height=h*scale),Spacer(1,5),Paragraph(html.escape(caption),self.small),Spacer(1,10)]))
    def finish(self):
        (ROOT/'Отчёт.md').write_text('\n'.join(self.md),encoding='utf-8')
        doc=SimpleDocTemplate(str(ROOT/'Отчёт.pdf'),pagesize=(595.276,841.89),leftMargin=57,rightMargin=57,topMargin=48,bottomMargin=48,
             title=f'Лабораторная работа {self.lab}. {self.title}. Вариант 10',author='Яковлев Иван',subject='Б24-517, осенний семестр 2026')
        def footer(canvas,doc):
            if doc.page>1:
                canvas.setFont('Sans',8); canvas.drawCentredString(297.6,27,str(doc.page))
        doc.build(self.story,onFirstPage=footer,onLaterPages=footer)

def general(r,s,d):
    r.h('1 Постановка и индивидуальный вариант')
    r.p('Работа выполнена для Яковлева Ивана, группа Б24-517, номер в группе N = 28. Для группы 517 индекс Q = 1. Год выполнения — 2026, осенний семестр, поэтому Y = 26.')
    r.formula('V = 1 + ((17·28 + 7·1 + 26) mod 20) = 1 + (509 mod 20) = 10\nseed = 10000 + 100·1 + 28 = 10128')
    r.p('Исходные данные синтетические: методические указания задают тему и минимальный масштаб, но не содержат числового набора для варианта 10. Параметры и процедура генерации сохранены в data.json и функции generate_data в main.py. Модель отделена от данных. Дополнительные задания и задания со звёздочкой не выполнялись.')

def implementation(r,lab):
    env=json.loads((ROOT/'results/environment.json').read_text(encoding='utf-8'))
    r.h('Реализация и воспроизводимость')
    r.p(f'Python {env["python"]}; HiGHS {env["highspy"]} через highspy; NumPy {env["numpy"]}; Matplotlib {env["matplotlib"]}. Версии зависимостей закреплены в requirements.txt. Вход — data.json; запуск — python main.py. Функции: generate_data, load_data, build_model, verify, main; общий интерфейс solve и файловая отчётность — common.py; оформление — reporting.py.')
    r.p('Для непрерывных задач выбран двойственный симплекс-метод. Presolve включён. Один поток, random_seed = 10128; лимит времени 120 с; primal_feasibility_tolerance и dual_feasibility_tolerance равны 10⁻⁸. Для MILP дополнительно mip_feasibility_tolerance = 10⁻⁸ и mip_rel_gap = 0; используется ветвление с отсечениями. Реальные журнал и LP-файл каждой задачи находятся в results. Время измерено perf_counter вокруг h.run, включая presolve, без генерации, записи файлов и построения рисунков.')
    r.p('Optimal означает подтверждённый солвером оптимум с учётом численных допусков. Infeasible означает отсутствие допустимого плана, Unbounded — неограниченность цели; Time limit требует отдельно рассматривать наличие допустимого решения и оценку зазора. Эти три статуса в основных экспериментах не получены. Программа прекращает обычное оформление при результате, отличном от Optimal, чтобы не выдать его за оптимальный.')
    r.p('Числа в таблицах отчёта округлены для чтения. Для воспроизведения плана и проверки допуска следует использовать CSV или JSON с полной точностью. Отдельные входные наборы сценариев сохранены в *_data.json. Регрессионные проверки запускаются командой python test_validation.py; обязательные проверки также действуют при python -O.')

def verification(r,s,names):
    r.h('Независимая проверка')
    r.p('Функция verify получает исходные предметные данные и числовой вектор решения. Она не обращается к объекту HiGHS и не использует матрицу build_model: заново суммирует ресурсы, спрос и стоимость средствами NumPy и Python. Каждое ограничение проверяется с абсолютным допуском 10⁻⁷; цель пересчитывается отдельно. Полные построчные проверки сохранены в *_constraints.csv, итоги — в *_verification.json.')
    rows=[]
    for name in names:
        z=json.loads((ROOT/'results'/f'{name}_verification.json').read_text(encoding='utf-8'))
        rows.append([name,'да' if z['feasible'] else 'нет',f'{z["max_violation"]:.2e}',f'{z["objective_error"]:.2e}'])
    r.table(['Проверка','Допустимо','Макс. нарушение','Ошибка цели'],rows,[135,75,135,135])
    all_checks=[json.loads(p.read_text(encoding='utf-8')) for p in (ROOT/'results').glob('*_verification.json')]
    r.p(f'В комплекте {len(all_checks)} файлов независимой проверки. Максимальное нарушение среди них — {max(z["max_violation"] for z in all_checks):.2e}; максимальная ошибка пересчёта цели — {max(z["objective_error"] for z in all_checks):.2e}. Некорректная длина вектора, NaN и бесконечные значения отклоняются до проверки ограничений.')

def lab1(r,s,d):
    general(r,s,d)
    base=s['scenarios']['base']; result=base['result']; useful=base['summary']['useful_m2']; waste=base['summary']['waste_m2']
    r.p(f'Цель — удовлетворить заказ на пять прямоугольных деталей, используя четыре типоразмера листа и минимизируя общую площадь расходуемого материала. Базовый оптимум: {num(result["objective"])} м², в том числе {num(useful)} м² полезной площади и {num(waste)} м² отходов.')
    r.h('2 Данные и схемы раскроя')
    r.table(['Деталь','Ширина, мм','Высота, мм','Заказ, шт.'],[[i['id'],i['width'],i['height'],i['demand']] for i in d['items']],[80,135,135,130])
    r.table(['Лист','Ширина, мм','Высота, мм','Доступно, шт.'],[[i['id'],i['width'],i['height'],i['available']] for i in d['stocks']],[80,135,135,130])
    r.p('Спрос генерируется вызовом numpy.random.default_rng(10128).integers(25, 46) последовательно для P1–P5. Геометрия и исходные запасы заданы фиксированно в генераторе. Горизонт — один плановый период. Дробный эквивалент числа листов допустим в усреднённой ЛП-постановке.')
    r.p(f'Сгенерированы {s["patterns"]} схемы двухэтапного гильотинного раскроя: сначала лист делится на горизонтальные полосы, затем каждая полоса — на детали одной высоты. Для каждой высоты перечисляются все ненулевые сочетания деталей, помещающиеся по ширине; затем все неубывающие сочетания полос, помещающиеся по высоте. Повторяющиеся векторы выпуска одного типа листа удаляются. Схемы сохранены в patterns.json и patterns.csv; для каждой есть геометрическое описание полос.')
    r.p('Ориентация деталей фиксирована; повороты, ширина реза и дефекты материала не учитываются. Полосы со смешанной высотой деталей и негильотинные схемы не рассматриваются. Оптимальность относится к заявленному классу схем, а не ко всем возможным двумерным раскроям.')
    r.h('3 Формальная ЛП-модель')
    r.p('Множества: I — пять позиций заказа; S — четыре типа листов; K — библиотека допустимых схем; K(s) — схемы типа s. Параметры: dᵢ — заказ, шт.; aᵢₖ — число деталей i в схеме k, шт./лист; Bₛ — запас листов, шт.; Aₛ — площадь листа, м²/лист. Переменная xₖ ≥ 0 — эквивалент числа листов, раскраиваемых по схеме k, шт.')
    r.formula('min F = Σₖ Aₛ₍ₖ₎ xₖ\nΣₖ aᵢₖ xₖ = dᵢ                      для каждой детали i\nΣₖ∈K(s) xₖ ≤ Bₛ                      для каждого типа s\nxₖ ≥ 0                               для каждой схемы k')
    r.p(f'Цель измеряется в м² за период. Равенства заказов запрещают перепроизводство. Полезная площадь U = Σᵢ widthᵢ·heightᵢ·dᵢ / 10⁶ постоянна, поэтому минимизация F эквивалентна минимизации отходов F − U. Полученная задача имеет {result["columns"]} непрерывных переменных и {result["rows"]} строк ограничений.')
    r.h('4 Базовый оптимальный план')
    patterns=json.loads((ROOT/'results/patterns.json').read_text(encoding='utf-8'))
    active=[(p,x) for p,x in zip(patterns,result['x']) if x>1e-7]
    r.table(['Схема','Лист','Листов','P1','P2','P3','P4','P5'],[[p['id'],d['stocks'][p['stock']]['id'],num(x)]+p['counts'] for p,x in active],[60,50,90,56,56,56,56,56])
    r.p(f'Применяется {len(active)} схем из {s["patterns"]}; общий расход — {num(sum(base["verification"]["used_sheets"]))} эквивалентных листа. Заказ выпускается точно: '+', '.join(f'{i["id"]}: {i["demand"]} шт.' for i in d['items'])+f' Коэффициент использования материала: {num(100*useful/result["objective"],3)}%.')
    r.image('cutting_patterns.png','Рисунок 1 Активные схемы базового плана',350)
    costs=[]
    for p,rc,x in zip(patterns,result['reduced_cost'],result['x']): costs.append(dict(pattern=p['id'],x=x,reduced_cost=rc))
    from common import csvwrite
    csvwrite(ROOT/'results/reduced_costs.csv',costs)
    zeros=[z for z in costs if z['x']<=1e-7]; positive=sum(z['reduced_cost']>1e-7 for z in zeros)
    r.p(f'Нулевые значения имеют {len(zeros)} схем: лишние схемы не нужны для выполнения точного заказа. У {positive} из них приведённая стоимость строго положительна — локальное введение такой схемы ухудшает цель при текущих двойственных оценках. Нулевая приведённая стоимость у остальных допускает вырожденность или альтернативные оптимальные планы, но сама по себе не доказывает существование отличного плана. Все значения приведены в reduced_costs.csv.')
    r.h('5 Сценарии и теневые цены')
    scarce=d['stocks'][s['scarce']]['id']; second=d['stocks'][s['second']]['id']
    r.p(f'Базовый сценарий использует исходные запасы. Дефицитный уменьшает запас {scarce} на 20%. Этот ресурс выбран автоматически по наиболее отрицательной теневой цене базового решения. Стрессовый уменьшает тот же запас на 40% и запас {second} на 20%. Все прочие данные неизменны.')
    r.table(['Сценарий','Площадь, м²','Отходы, м²','ΔF, м²','Прогноз ΔF'],[[n,num(z['summary']['area_m2']),num(z['summary']['waste_m2']),num(z['summary']['objective_change']),num(z['summary']['shadow_prediction'])] for n,z in s['scenarios'].items()],[90,100,100,95,95])
    r.table(['Ресурс','Использовано','Запас','Цена, м²/лист','ΔF при +0,01'],[[z['stock'],num(z['used']),z['capacity'],num(z['marginal_m2_per_sheet']),num(z['actual_change'],7)] for z in s['shadows']],[70,100,80,120,110])
    best=s['shadows'][s['scarce']]
    r.p(f'Первоочередной ресурс для увеличения — {scarce}: его теневая цена {num(best["marginal_m2_per_sheet"])} м²/лист. Это эффект замещения схем, а не уменьшение площади самого листа. При добавлении 0,01 листа фактическое изменение {num(best["actual_change"],7)} м² сравнивается с прогнозом {num(best["predicted_change"],7)} м². Полное использование запаса не гарантирует полезности его расширения: у активного ограничения цена может быть нулевой.')
    matches=all(abs(z['summary']['objective_change']-z['summary']['shadow_prediction'])<=1e-7 for name,z in s['scenarios'].items() if name!='base')
    r.p(('Для обоих ухудшений линейный прогноз Σₛ λₛ·ΔBₛ совпал с фактическим изменением цели в пределах допуска.' if matches else 'Для части ухудшений линейный прогноз отличается от факта: изменение правой части вышло за область действия базовых двойственных оценок.')+' Это проверка для конкретных изменений; диапазон устойчивости базиса не вычислялся. Площадь и число листов — разные показатели: замена на более крупные листы может уменьшить их число при росте площади. Все три сценария Optimal, конфликтующих ограничений в них нет.')
    r.p('Расход типов листа S1–S4, эквивалент шт.: '+'; '.join(name+' — '+', '.join(num(v) for v in z['verification']['used_sheets']) for name,z in s['scenarios'].items())+'. Полные планы схем всех сценариев приложены в *_solution.csv. Решения четырёх проверочных опытов увеличения запаса также независимо проверены.')
    r.image('stock_use.png','Рисунок 2 Расход типов листа в сценариях',240)
    verification(r,s,['base','deficit','stress'])
    r.p('Дополнительно для всей библиотеки заново проверяются сумма ширин деталей каждой полосы, равенство высот деталей высоте полосы, сумма высот полос и соответствие вектора выпуска геометрии. Проверены все схемы, включая неиспользуемые.')
    implementation(r,1)
    r.h('Вывод и практическая реализуемость')
    r.p(f'План покрывает весь заказ при минимальной площади {num(result["objective"])} м² в выбранной библиотеке схем; отходы составляют {num(waste)} м². Расширение запаса {scarce} следует оценивать в первую очередь по найденной теневой цене. Геометрия каждой схемы реализуема, однако дробное число листов требует усреднения по повторяющимся заказам. Для разовой производственной партии потребуются целые листы, припуски на рез, условия поворота, остатки и настройка станка; независимое округление переменных не гарантирует выполнения заказа и запасов. Целочисленное расширение не выполнялось.')

def lab2(r,s,d):
    general(r,s,d); base=s['scenarios']['base']; res=base['result']; v=base['verification']; i,j=s['busiest']
    r.p(f'Решается транспортная задача для четырёх складов и шести магазинов за сутки. Цель — минимизировать стоимость перевозок и штраф за неудовлетворённый спрос с учётом ограничений маршрутов. Товар делим: единица — палета-эквивалент. Базовый оптимум равен {num(res["objective"])} руб./сут; {num(v["total_deficit"])} палет/сут спроса остаются неудовлетворёнными.')
    r.h('2 Данные и структура сети')
    r.table(['Склад','Запас, палет/сут']+d['shops'],[[d['warehouses'][i],d['supply'][i]]+[str(d['cost'][i][j])+'/'+str(d['capacity'][i][j]) for j in range(6)] for i in range(4)],[45,105]+[55]*6)
    r.p('В ячейках маршрутов указаны тариф / пропускная способность: руб./палету и палет/сут соответственно. Существуют все 24 направленные дуги склад → магазин.')
    r.table(['Магазин']+d['shops'],[['Спрос, палет/сут']+d['demand'],['Штраф, руб./палету']+d['penalty']],[150]+[55]*6)
    r.p(f'Генератор — default_rng(10128). В указанном порядке выбираются целые равномерные значения: запасы [90,121), спрос [65,96), тарифы [8,46), ёмкости [25,61), штрафы [80,131). Правая граница исключается. Общий запас — {num(sum(d["supply"]))}, спрос — {num(sum(d["demand"]))} палет/сут: дефицит не менее {num(max(0,sum(d["demand"])-sum(d["supply"])))} палет/сут неизбежен даже без ограничений маршрутов.')
    r.p('Для потоковой интерпретации вводятся общий источник S, фиктивный поставщик D и сток T. Дуги S→W имеют ёмкости запасов и нулевые тарифы; W→M — транспортные маршруты; S→D имеет ёмкость суммарного спроса; D→M — дефицит со штрафным тарифом; M→T несут фиксированный спрос. В явной ЛП используются 30 переменных, дополнительные потоки восстанавливаются из них. Полная сеть с потоками, ёмкостями и тарифами сохранена в *_network_arcs.csv.')
    r.h('3 Формальная ЛП-модель')
    r.p('I — четыре склада, J — шесть магазинов. sᵢ — запас, dⱼ — спрос, uᵢⱼ — ёмкость маршрута (палет/сут); cᵢⱼ — транспортный тариф и pⱼ — штраф (руб./палету). Непрерывные переменные xᵢⱼ — доставка, zⱼ — неудовлетворённый спрос (палет/сут).')
    r.formula('min F = ΣᵢΣⱼ cᵢⱼ xᵢⱼ + Σⱼ pⱼ zⱼ\nΣⱼ xᵢⱼ ≤ sᵢ                            для каждого склада i\nΣᵢ xᵢⱼ + zⱼ = dⱼ                       для каждого магазина j\n0 ≤ xᵢⱼ ≤ uᵢⱼ;  0 ≤ zⱼ ≤ dⱼ')
    r.p('F измеряется в руб./сут. Штраф — экономическая оценка потери сервиса, а не реальная доставка. Наличие z гарантирует допустимость при любых неотрицательных входных данных: можно выбрать x = 0, z = d. Это не означает приемлемого качества обслуживания. Модель предполагает один товар, линейные тарифы и отсутствие фиксированной цены рейса, времени в пути и неделимых автомобилей.')
    r.h('4 Базовый план и сеть')
    flow=np.array(res['x'][:24]).reshape(4,6)
    r.table(['Поток, палет/сут']+d['shops']+['Итого'],[[d['warehouses'][k]]+[num(x) for x in flow[k]]+[num(flow[k].sum())] for k in range(4)]+[['Дефицит']+[num(x) for x in res['x'][24:]]+[num(sum(res['x'][24:]))]],[120]+[45]*6+[90])
    r.p(f'Перевозки стоят {num(v["transport_cost"])} руб./сут, штрафы — {num(v["penalty_cost"])} руб./сут. Использовано {num(flow.sum())} из {num(sum(d["supply"]))} палет запасов; {num(v["total_deficit"])} палет спроса не покрываются. Распределение дефицита определяется штрафом и доступными маршрутами. Нулевые потоки означают, что эти направления не нужны в выбранном оптимальном плане.')
    r.image('network.png','Рисунок 1 Сеть транспортных маршрутов и фиктивного дефицита',420)
    r.p('На рисунке показаны все 13 узлов и 41 дуга расширенной сети, включая общий источник S и сток T. Для каждой дуги подписаны поток / ёмкость. Нулевые транспортные потоки обозначены пунктиром, дуги штрафного дефицита — оранжевым штрихом. Тарифы приведены в таблице данных и сетевом CSV.')
    r.h('5 Сценарии и жадная эвристика')
    r.p(f'Самая загруженная по абсолютному потоку дуга — W{i+1}→M{j+1}, {num(flow[i,j])} палет/сут из {d["capacity"][i][j]}. При равенстве выбирается первая по индексам. Дефицитный сценарий увеличивает весь спрос на 20%; перегрузка уменьшает ёмкость выбранной дуги на 20%; отказ закрывает её полностью; стресс одновременно увеличивает спрос на 20% и закрывает эту дугу.')
    r.table(['Сценарий','Цель, руб./сут','Дефицит','Ущерб, руб./сут','Зазор жадного, %'],[[n,num(z['summary']['cost']),num(z['summary']['deficit']),num(z['summary']['damage']),num(z['summary']['greedy_gap_percent'],3)] for n,z in s['scenarios'].items()],[100,105,75,100,100])
    ds=s['scenarios']['deficit']['summary']; fail=s['scenarios']['arc_failure']['summary']; stress=s['scenarios']['stress']['summary']
    r.p(f'При росте спроса дефицит меняется с {num(v["total_deficit"])} до {num(ds["deficit"])} палет/сут, стоимость растёт на {num(ds["damage"])} руб./сут. Отказ наиболее загруженной дуги увеличивает цель на {num(fail["damage"])} руб./сут; дефицит составляет {num(fail["deficit"])} палет/сут. Поток перераспределяется, меняются транспортная стоимость и распределение потерь между магазинами. Совместный стресс даёт {num(stress["cost"])} руб./сут. Дополнительный ущерб отказа при повышенном спросе равен {num(stress["cost"]-ds["cost"])} руб./сут, поэтому эффекты не обязаны складываться линейно.')
    r.p('Жадная эвристика сортирует маршруты по тарифу и последовательно отправляет минимум остатка запаса, остатка спроса и ёмкости; маршруты дороже штрафа пропускаются. Неисполненный спрос становится дефицитом. Эвристика допустима и проверяется тем же независимым кодом, но не пересматривает ранние решения и не учитывает альтернативные издержки маршрутов. Зазор = 100·(Fgreedy − Fopt)/Fopt.')
    r.table(['Сценарий','Оптимум','Жадный','HiGHS, мс','Жадный, мс'],[[n,num(z['summary']['cost']),num(z['summary']['greedy_cost']),num(z['summary']['seconds']*1000,3),num(z['summary']['greedy_seconds']*1000,3)] for n,z in s['scenarios'].items()],[105,100,100,90,85])
    bs=base['summary']; faster=sum(z['summary']['greedy_seconds']<z['summary']['seconds'] for z in s['scenarios'].values())
    r.p(f'В базе жадный план стоит {num(bs["greedy_cost"])} руб./сут, что на {num(bs["greedy_cost"]-bs["cost"])} руб./сут ({num(bs["greedy_gap_percent"],3)}%) хуже оптимума. В {faster} из {len(s["scenarios"])} запусков он быстрее на данном компьютере; эти времена — измерения единичных запусков, а не статистический бенчмарк.')
    r.image('scenario_costs.png','Рисунок 2 Стоимость перевозки и штрафы по сценариям',240)
    r.h('6 Узкие места и двойственная интерпретация')
    r.table(['Дуга','Поток = ёмкость','Цена, руб./палету','ΔF при +0,01'],[[z['warehouse']+'→'+z['shop'],num(z['flow']),num(z['marginal']),num(z['actual_change'],6)] for z in s['bottlenecks']],[100,130,120,130])
    best=min(s['bottlenecks'],key=lambda z:z['marginal']) if s['bottlenecks'] else None
    r.p('Для ограничений склада αᵢ — row_dual строки запаса, βⱼ — row_dual баланса магазина. Приведённая стоимость дуги rᵢⱼ = cᵢⱼ − αᵢ − βⱼ. Если положительный поток достиг верхней границы, отрицательное rᵢⱼ показывает локальное уменьшение цели при увеличении её ёмкости на единицу. '+(f'Максимальный локальный выигрыш среди насыщенных дуг даёт {best["warehouse"]}→{best["shop"]}: цена {num(best["marginal"])} руб./палету. ' if best else '')+'Для каждой насыщенной дуги ёмкость отдельно увеличена на 0,01. Прогноз и факт приведены в bottlenecks.csv; все проверочные решения также прошли независимую проверку.')
    r.p(f'Самый большой поток и самая дорогая потеря пропускной способности — разные признаки. У самой загруженной W{i+1}→M{j+1} поток {num(flow[i,j])} ниже ёмкости {num(d["capacity"][i][j])}; резерв составляет {num(d["capacity"][i][j]-flow[i,j])} палет/сут. Первое небольшое уменьшение ёмкости в пределах резерва не меняет оптимум. Большой отказ выходит за локальный диапазон двойственной оценки. Значения всех узловых оценок сохранены в node_prices.csv.')
    verification(r,s,['base','deficit','arc_overload','arc_failure','stress','base_greedy'])
    r.p('Проверяются балансы всех 13 узлов расширенной сети S, D, W1–W4, M1–M6, T; на источнике и стоке учитывается внешний поток ±Σd. Границы проверяются на каждой из 41 дуги. Балансы вынесены в *_node_balances.csv. Проверены также все пять жадных планов, включая пересчёт их стоимости.')
    implementation(r,2)
    r.h('Вывод и практическая реализуемость')
    r.p(f'ЛП определяет экономически наименее дорогой способ распределения дефицитного товара. Разница исходного спроса и запаса составляет {num(sum(d["demand"])-sum(d["supply"]))} палет/сут; штрафная постановка даёт допустимый оптимум даже при нехватке товара. В первую очередь следует рассматривать увеличение запасов и снятие экономически значимых ограничений маршрутов, сопоставляя эффект с реальной ценой расширения. Для внедрения нужны ограничения минимального уровня обслуживания, размеры партий, доступность транспорта, сроки и достоверные оценки штрафов. Дробные палеты в сценариях интерпретируются как усреднённые объёмы.')

def lab3(r,s,d):
    general(r,s,d); base=s['scenarios']['base']; n=d['n']
    r.p(f'Для {n} SKU и шести категорий спроса требуется выбрать минимальное число позиций на полке. Количество отгруженного товара непрерывно; открытие позиции бинарно. Базовое решение включает {num(base["milp"]["objective"])} SKU; LP-релаксация даёт нижнюю оценку {num(base["lp"]["objective"],6)} позиции. Интегральный зазор составляет {num(base["summary"]["integrality_gap_percent"],6)}%, конечный зазор ветвления — {num(base["summary"]["branch_gap_percent"])}%.')
    r.h('2 Данные и допущения')
    r.table(['SKU','Категория','U, уп./нед.','Ширина, см'],[[f'{i+1:02}',d['category'][i]+1,d['capacity'][i],d['width'][i]] for i in range(n)],[80,100,150,150])
    r.table(['Категория']+[str(k+1) for k in range(6)],[['Спрос, уп./нед.']+d['demand']],[150]+[55]*6)
    r.p(f'Ширина полки — {d["shelf_width"]} см. Генератор default_rng(10128) сначала получает 20 ёмкостей U из [30,91), затем 20 ширин из [3,9). Категория i-го SKU равна (i−1) mod 6. Спрос категории равен ceil(1,12·max U) при наличии нескольких SKU; для одиночного SKU в опыте масштаба — floor(0,85·U). Полка для n>12 равна ceil(0,82·Σw), при n≤12 — Σw, чтобы малый тест не исключался искусственно по ширине.')
    r.p('SKU покрывает только свою категорию; внутри категории товары считаются взаимозаменяемыми в единицах упаковок-эквивалентов. U — максимальный объём реализации за неделю при наличии SKU. Ширина — фиксированное место для представления позиции; продажи пополняются со склада и не равны количеству упаковок, одновременно стоящих на полке. Не учитываются прибыль, цены, взаимодействие брендов, обязательный минимум экспозиции и кратность коробов.')
    r.h('3 Формальная MILP-модель')
    r.p('I — набор SKU, K — шесть категорий; Iₖ — SKU категории k. Параметры: Uᵢ — максимум реализации, dₖ — спрос (уп./нед.); wᵢ — ширина позиции, L — длина полки (см). Переменные yᵢ ∈ {0,1} обозначают наличие SKU на полке; qᵢ ≥ 0 — объём продаж (уп./нед.).')
    r.formula('min F = Σᵢ yᵢ\nΣᵢ∈Iₖ qᵢ = dₖ                           для каждой категории k\n0 ≤ qᵢ ≤ Uᵢ                              для каждого SKU i\nqᵢ ≤ Mᵢ yᵢ,  Mᵢ = Uᵢ                    для каждого SKU i\nΣᵢ wᵢ yᵢ ≤ L\nyᵢ ∈ {0,1}')
    r.p('F измеряется в числе позиций. Связка qᵢ ≤ Uᵢyᵢ запрещает продажи отсутствующей позиции. Равенство спроса исключает ненужное перепроизводство. Бинарная логика «позиция присутствует целиком» не воспроизводится непрерывной ЛП-релаксацией. Модель содержит 20 бинарных и 20 непрерывных переменных, 27 строк ограничений и явные границы объёмов.')
    r.h('4 LP-релаксация и оптимальный ассортимент')
    r.p('В LP-релаксации yᵢ заменяются на 0 ≤ yᵢ ≤ 1. Нижняя оценка получается при оплате дробной доли позиции. Интегральный зазор для минимизации определён как 100·(FMILP − FLP)/FMILP. Это зазор между двумя моделями, а не mip_gap солвера.')
    rows=[]
    for i in range(n): rows.append([f'{i+1:02}',d['category'][i]+1,num(base['lp']['x'][i],6),num(base['lp']['x'][n+i]),num(base['milp']['x'][i]),num(base['milp']['x'][n+i])])
    r.table(['SKU','Кат.','y LP','q LP','y MILP','q MILP'],rows,[65,55,100,85,80,95])
    fractional=[i for i in range(n) if 1e-7<base['lp']['x'][i]<1-1e-7]
    if fractional:
        i=fractional[0]
        r.p(f'Например, LP допускает SKU{i+1:02} с y = {num(base["lp"]["x"][i],6)} и q = {num(base["lp"]["x"][n+i])} уп./нед.: обслуживается часть спроса, но учитывается только {num(base["lp"]["x"][i]*100,2)}% позиции на полке. Такую долю решения «ввести SKU» реализовать нельзя.')
    r.p('В целочисленном плане выбраны: '+', '.join(base['verification']['selected'])+f'. Использовано {num(base["verification"]["width_used"])} из {d["shelf_width"]} см.')
    lower_counts=[int(np.ceil(d['demand'][k]/max(d['capacity'][i] for i in range(n) if d['category'][i]==k))) for k in range(6)]
    lower_bound=sum(lower_counts)
    r.p('Для каждой категории число позиций не меньше ceil(спрос / максимальная ёмкость одного SKU). По шести категориям нижние границы равны '+', '.join(map(str,lower_counts))+f'; в сумме не менее {lower_bound}. '+('Найденный допустимый план достигает этой границы, что даёт простое дополнительное доказательство оптимальности. ' if abs(base['milp']['objective']-lower_bound)<1e-7 else 'Солвер подтверждает оптимальность с учётом остальных ограничений. ')+'Модель не задаёт вторичной цели качества ассортимента; разные наборы с одной и той же минимальной целью могут быть равноценны.')
    r.h('5 Три сценария и жадная эвристика')
    r.p('База использует исходные параметры. Дефицитный сценарий уменьшает U всех SKU на 20% без изменения спроса. Стресс одновременно уменьшает U на 20% и увеличивает спрос всех категорий на 20%. SKU и ширина полки сохраняются.')
    r.table(['Сценарий','LP','MILP','Интегр. зазор, %','Ветвление, %','Жадный'],[[name,num(z['lp']['objective'],6),num(z['milp']['objective']),num(z['summary']['integrality_gap_percent'],3),num(z['summary']['branch_gap_percent']),num(z['summary']['greedy_count'])] for name,z in s['scenarios'].items()],[90,90,65,100,80,55])
    for name,z in s['scenarios'].items():
        r.p(name+': '+', '.join(z['verification']['selected'])+'.')
    r.image('assortment.png','Рисунок 1 Состав ассортимента по сценариям',220)
    r.p('Число позиций по сценариям: '+', '.join(name+' — '+num(z['milp']['objective']) for name,z in s['scenarios'].items())+'. В приведённых выше наборах видны изменения состава. Различие наборов само по себе не доказывает единственности или обязательности каждого переключения: при равной цели HiGHS может выбрать другой оптимальный набор. Уменьшение ёмкостей усиливает требования к загрузке SKU и к нижней оценке LP.')
    r.p('Жадная эвристика выбирает ещё не выбранный SKU с максимальным объёмом реально покрываемого остатка спроса при наличии места на полке; при равенстве предпочитает меньшую ширину, затем меньший индекс. Продажи равны покрытому остатку. Если кандидатов нет, эвристика возвращает отсутствие допустимого плана. Её результат и зазор указаны в таблицах. Совпадение с MILP на отдельных наборах не является гарантией для произвольного сочетания ёмкостей и ограниченной полки.')
    r.table(['Сценарий','MILP, мс','Жадный, мс','Зазор жадного, %'],[[name,num(z['summary']['seconds']*1000,3),num(z['summary']['greedy_seconds']*1000,3),num(z['summary']['greedy_gap_percent'],3)] for name,z in s['scenarios'].items()],[120,120,120,120])
    r.h('6 Выбор big-M и опыт с большим значением')
    r.p('Mᵢ = Uᵢ — естественная максимально допустимая продажа SKU. Она достаточна и является минимальной глобальной верхней оценкой, вытекающей из отдельного ограничения qᵢ ≤ Uᵢ. Для этой модели её можно дополнительно усилить до min(Uᵢ,dₖ), но в отчётном эксперименте используется Uᵢ. При Mᵢ < фактически необходимого qᵢ допустимые решения могут быть потеряны.')
    r.p('В эксперименте M заменяется на 1000·U и 10⁶·U, а отдельная граница q ≤ U сохраняется. Поэтому множество целочисленных решений остаётся тем же, но LP-релаксация становится слабее. В таблице приведены реальные измерения на одних и тех же данных.')
    r.table(['Множитель M','LP-оценка','MILP','Зазор LP, %','Время, мс','Узлы'],[[z['M_factor'],f'{z["lp_bound"]:.8g}',num(z['milp_objective']),num(z['integrality_gap_percent'],6),num(z['milp_seconds']*1000,3),z['nodes']] for z in s['bigM']],[90,100,55,100,85,50])
    r.p('Большой M уменьшает LP-оценку практически до нуля, а интегральный зазор приближается к 100%. Число узлов и время ветвления приведены в таблице: presolve и отсечения могут компенсировать слабость исходной релаксации на малой задаче. Результат не означает, что большое M обязано замедлять каждый запуск. Исходная релаксация ухудшилась, а масштаб коэффициентов увеличился. Все решения опыта независимо проверены с фактически использованным M.')
    r.h('7 Рост масштаба и кривая времени и зазора')
    r.p('Рассмотрены 10, 20 и 40 SKU при шести категориях. Для каждого масштаба данные вновь генерируются с seed 10128 и сохраняются в scale_*_data.json. Это сопоставимые синтетические наборы, не вложенные выборки: ширины при другом n получаются после другого числа генераций ёмкостей. Для каждого размера выполнены три решения с новым объектом HiGHS; таблица показывает медианы времени. Все исходные повторы приведены в scaling.csv.')
    rows=[]
    for n in [10,20,40]:
        z=[q for q in s['scaling'] if q['objects']==n]; first=z[0]
        rows.append([n,num(np.median([q['seconds'] for q in z])*1000,3),num(first['lp_bound'],5),num(first['milp_objective']),num(first['integrality_gap_percent'],3),num(first['branch_gap_percent'])])
    r.table(['SKU','Медиана, мс','LP','MILP','Зазор LP, %','Итоговый gap, %'],rows,[45,100,90,65,90,90])
    r.image('scaling.png','Рисунок 2 Время решения и зазор при увеличении масштаба',230)
    r.p('На всех размерах достигнут подтверждённый оптимум с нулевым итоговым gap. Тренд времени для столь малых структурированных задач может быть немонотонным: сказываются presolve, отсечения и различия наборов. Эксперимент не доказывает экспоненциальный рост; в общем случае комбинаций бинарного выбора 2ⁿ, но рассмотренная структура по категориям существенно облегчает поиск.')
    verification(r,s,['base_lp','base_milp','deficit_milp','stress_milp','base_greedy','bigM_1000000_milp'])
    r.p('Помимо баланса категорий и длины полки отдельно проверяются 0 ≤ q ≤ U, 0 ≤ y ≤ 1, связки q ≤ My и расстояние y до ближайшего целого. Для LP требование целочисленности отключено. Проверки имеются для всех сценариев, релаксаций, опытов M и повторов масштаба, включая допустимые жадные планы.')
    implementation(r,3)
    r.h('Вывод и практическая реализуемость')
    r.p(f'В базовом сценарии получен ассортимент из {num(base["milp"]["objective"])} полностью выбираемых SKU, покрывающий спрос всех шести категорий и укладывающийся в полку. Доля позиции в LP не реализуема как дискретный выбор, поэтому нужен MILP. Изменения состава, числа позиций и сравнение с эвристикой показаны для каждого сценария. Для внедрения необходимы фактические данные о взаимозаменяемости, прибыльности, кратности упаковок и выкладке. Непрерывные объёмы допустимы как усреднение на неделю; решение не является рекомендацией для реального магазина без этих уточнений.')

def build_report():
    meta=json.loads((ROOT/'metadata.json').read_text(encoding='utf-8')); d=json.loads((ROOT/'data.json').read_text(encoding='utf-8')); s=json.loads((ROOT/'results/summary.json').read_text(encoding='utf-8'))
    titles={1:'ЛП-модель распределения ресурсов при раскрое листов',2:'Транспортная задача с дефицитом и штрафами',3:'Минимальный ассортимент при покрытии спроса'}
    r=Report(meta['lab'],titles[meta['lab']]); {1:lab1,2:lab2,3:lab3}[meta['lab']](r,s,d)
    r.h('Источники')
    r.p('Кузьмин А. А. Методы оптимизации. Линейное программирование. Комплекс лабораторных работ. 2026. Индивидуальный вариант и обязательные требования взяты из предоставленного методического документа.')
    r.md.append('HiGHS Documentation. [Интерфейс Python](https://ergo-code.github.io/HiGHS/dev/interfaces/python/example-py/), [Параметры солвера](https://ergo-code.github.io/HiGHS/dev/options/definitions/). Дата обращения: 06.11.2026.\n')
    r.story.append(Paragraph('HiGHS Documentation. <link href="https://ergo-code.github.io/HiGHS/dev/interfaces/python/example-py/">Интерфейс Python</link>, <link href="https://ergo-code.github.io/HiGHS/dev/options/definitions/">Параметры солвера</link>. Дата обращения: 06.11.2026.',r.body))
    r.finish()

if __name__=='__main__': build_report()
